import {Chess} from './chess.js';
const initial=Object.fromEntries(new Chess().board().flat().filter(Boolean).map(p=>[p.square,p.color==='w'?p.type.toUpperCase():p.type]));
const make=(id,pieces,answers,taskTitle,prompt,hint,explanation)=>({id,pieces,answers,taskTitle,prompt,hint,explanation,introduction:prompt,positionKind:'boardStudy',goal:'square',familyId:'board-foundations',skillId:id.startsWith('orientation-')?'board-orientation':'starting-position',syncGroup:'board-v1'});
export const BOARD_EXERCISES=[
 make('orientation-white-right',{},['h1'],'Светлый угол у белых','Белые находятся снизу. Доску ставят светлой угловой клеткой справа от белых: здесь это h1.','Ищи нижний правый угол.','Справа рядом с белыми — светлая клетка h1.'),
 make('orientation-white-left',{},['a1'],'Тёмный угол у белых','Нажми на тёмную угловую клетку слева от белых. Белые находятся снизу.','Ищи нижний левый угол.','Слева рядом с белыми — тёмная клетка a1.'),
 make('orientation-black-right',{},['a8'],'Светлый угол у чёрных','Чёрные находятся сверху и смотрят к белым. Нажми на светлый угол справа от чёрных.','Справа от чёрных — слева на нашем экране, вверху.','Справа от чёрных — светлая клетка a8. Она слева вверху на нашем экране.'),
 make('orientation-black-left',{},['h8'],'Тёмный угол у чёрных','Нажми на тёмный угол слева от чёрных. Чёрные находятся сверху.','Слева от чёрных — справа на экране, вверху.','Слева от чёрных — тёмная клетка h8.'),
 make('setup-rooks',initial,['a1','h1','a8','h8'],'Ладьи стоят в углах','Это вся начальная расстановка. Найди любую ладью в углу доски.','У каждого игрока две ладьи — в крайних углах своего ряда.','Ладьи стоят по углам: a1, h1, a8 и h8.'),
 make('setup-knights',initial,['b1','g1','b8','g8'],'Кони рядом с ладьями','Нажми на любого коня в начальной расстановке.','От угла к середине: ладья, затем конь.','Кони стоят рядом с ладьями: b1, g1, b8 и g8.'),
 make('setup-bishops',initial,['c1','f1','c8','f8'],'Слоны рядом с конями','Нажми на любого слона в начальной расстановке.','От угла к середине: ладья, конь, затем слон.','Слоны стоят рядом с конями: c1, f1, c8 и f8.'),
 make('setup-pawns',initial,[...'abcdefgh'].flatMap(f=>[f+'2',f+'7']),'Пешки перед фигурами','Нажми на любую пешку в начальной расстановке.','Восемь белых пешек — на втором ряду, восемь чёрных — на седьмом.','Пешки стоят рядами перед остальными фигурами: белые на втором, чёрные на седьмом.'),
 make('setup-white-queen',initial,['d1'],'Белый ферзь на светлом','Ферзь начинает на клетке своего цвета. Белый ферзь — на светлой d1. Посмотрим на него.','У белых ферзь на d1, король справа от него на e1.','Белый ферзь стоит на светлой клетке d1.'),
 make('setup-black-queen',initial,['d8'],'Чёрный ферзь на тёмном','Найди чёрного ферзя на клетке его цвета.','Чёрный ферзь стоит на тёмной d8 напротив белого ферзя.','Чёрный ферзь стоит на тёмной клетке d8. Ферзи начинают напротив друг друга.'),
 make('setup-white-king',initial,['e1'],'Белый король рядом с ферзём','Нажми на белого короля в начальной расстановке.','Белый король стоит на e1, рядом с белым ферзём d1.','Белый король стоит на e1, рядом с ферзём.'),
 make('setup-black-king',initial,['e8'],'Чёрный король рядом с ферзём','Нажми на чёрного короля в начальной расстановке.','Чёрный король стоит на e8 напротив белого короля e1.','Чёрный король стоит на e8. Теперь ты рассмотрел места всех фигур в начальной расстановке.')
];
const placements=[
 ['place-white-rook','a1','R','Поставь белую ладью','Белая ладья ждёт своего места. Нажми на пустой угол, где она стоит в начале партии.','Белые снизу. У белых ладьи стоят по углам нижнего ряда.'],
 ['place-black-knight','b8','n','Поставь чёрного коня','В начальной расстановке не хватает чёрного коня. Нажми на его пустое место рядом с ладьёй.','Чёрные сверху. От угла к середине: ладья, конь, слон.'],
 ['place-white-queen','d1','Q','Поставь белого ферзя','Белый ферзь начинает на светлой клетке. Найди его пустое место рядом с королём.','Белые снизу. Белый ферзь стоит на светлой d1, рядом с королём e1.'],
 ['place-black-king','e8','k','Поставь чёрного короля','Верни чёрного короля на пустое место рядом с чёрным ферзём.','Чёрный ферзь на d8, король рядом на e8.']
];
BOARD_EXERCISES.push(...placements.map(([id,square,placePiece,taskTitle,prompt,hint])=>{
 const pieces={...initial};delete pieces[square];
 return {...make(id,pieces,[square],taskTitle,prompt,hint,'Фигура на месте! Начальная расстановка снова полная.'),goal:'placePiece',placePiece};
}));
const whiteBackRank=[
 ['rook-left','a1','R','Ладья в левом углу','Начнём с пустой доски. Белые снизу. Поставим белую ладью в нижний левый угол.','Нижний левый угол — a1.'],
 ['rook-right','h1','R','Вторая ладья справа','Первая ладья уже стоит слева. Поставь вторую белую ладью в нижний правый угол.','Ладьи занимают оба угла нижнего ряда: a1 и h1.'],
 ['knight-left','b1','N','Конь рядом с левой ладьёй','Поставь коня рядом с левой ладьёй, к середине доски.','Слева в нижнем ряду: ладья на a1, конь на b1.'],
 ['knight-right','g1','N','Конь рядом с правой ладьёй','Теперь поставь коня рядом с правой ладьёй, к середине доски.','Справа в нижнем ряду: ладья на h1, конь на g1.'],
 ['bishop-left','c1','B','Слон рядом с левым конём','Ладьи и кони здесь уже поставлены. Добавим слона рядом с левым конём, ближе к середине.','От левого угла к середине: ладья a1, конь b1, слон c1.'],
 ['bishop-right','f1','B','Слон рядом с правым конём','Добавь второго слона рядом с правым конём, ближе к середине.','От правого угла к середине: ладья h1, конь g1, слон f1.'],
 ['queen','d1','Q','Ферзь на светлой клетке','Остались два места посередине нижнего ряда. Поставь белого ферзя на светлую клетку.','Белый ферзь на светлой d1. Слева от неё стоит белый слон c1.'],
 ['king','e1','K','Король рядом с ферзём','Поставь белого короля на оставшееся место рядом с ферзём в нижнем ряду.','Белый король стоит на e1, справа от ферзя d1.']
];
BOARD_EXERCISES.push(...whiteBackRank.map(([name,square,placePiece,taskTitle,prompt,hint],i)=>({
 ...make('build-white-'+name,Object.fromEntries(whiteBackRank.slice(0,i).map(([,sq,piece])=>[sq,piece])),[square],taskTitle,prompt,hint,i===7?'Первый ряд белых собран! Пешки и чёрные фигуры ещё впереди.':'Фигура на месте. Постепенно собираем первый ряд белых.'),goal:'placePiece',placePiece
})));
const pawnNeighbours=['левой ладьёй','левым конём','левым слоном','ферзём','королём','правым слоном','правым конём','правой ладьёй'];
BOARD_EXERCISES.push(...[...'abcdefgh'].map((file,i)=>{
 const square=file+'2',intro=i===0?'Первый ряд белых здесь уже стоит. Добавим перед ним восемь пешек. ':i===4?'Первый ряд и четыре пешки здесь уже поставлены. Добавим остальные четыре. ':'';
 const prompt=intro+`Поставь белую пешку перед ${pawnNeighbours[i]}, на второй ряд снизу.`;
 const pieces=Object.fromEntries([...whiteBackRank.map(([,sq,piece])=>[sq,piece]),...[...'abcdefgh'].slice(0,i).map(f=>[f+'2','P'])]);
 return {...make('build-pawn-'+file,pieces,[square],`Пешка перед ${pawnNeighbours[i]}`,prompt,`Белые пешки стоят на втором ряду. Сейчас нужна клетка ${square}, перед ${pawnNeighbours[i]}.`,i===7?'Все восемь белых пешек на месте. Белая сторона расставлена; чёрные фигуры ещё впереди.':'Пешка на месте. Постепенно заполняем второй ряд белых.'),goal:'placePiece',placePiece:'P'};
}));
const blackBackRank=[
 ['rook-left','a8','r','Чёрная ладья в верхнем углу','Все белые фигуры здесь уже стоят. Белые снизу, чёрные сверху. Поставим чёрную ладью в левый верхний угол экрана.','Слева вверху экрана — a8. Это правый угол для игрока чёрными.'],
 ['rook-right','h8','r','Вторая чёрная ладья','Поставь вторую чёрную ладью в правый верхний угол экрана.','Другой верхний угол — h8. Доску не поворачиваем.'],
 ['knight-left','b8','n','Чёрный конь рядом с ладьёй','Поставь чёрного коня рядом с верхней ладьёй слева на экране, к середине ряда.','От левого верхнего угла к середине: ладья a8, конь b8.'],
 ['knight-right','g8','n','Второй чёрный конь','Поставь второго чёрного коня рядом с верхней ладьёй справа на экране, к середине ряда.','От правого верхнего угла к середине: ладья h8, конь g8.'],
 ['bishop-left','c8','b','Чёрный слон рядом с конём','Белые, чёрные ладьи и кони здесь уже стоят. Добавим чёрного слона рядом с конём слева на экране, ближе к середине.','В верхнем ряду слева на экране: ладья a8, конь b8, слон c8.'],
 ['bishop-right','f8','b','Второй чёрный слон','Добавь второго чёрного слона рядом с конём справа на экране, ближе к середине верхнего ряда.','В верхнем ряду справа на экране: ладья h8, конь g8, слон f8.'],
 ['queen','d8','q','Чёрный ферзь на тёмном','Остались два места в середине верхнего ряда. Поставь чёрного ферзя на тёмную клетку напротив белого ферзя.','Чёрный ферзь на тёмной d8, напротив белого ферзя d1.'],
 ['king','e8','k','Чёрный король рядом с ферзём','Поставь чёрного короля на оставшееся место рядом с чёрным ферзём в верхнем ряду.','Чёрный король на e8, напротив белого короля e1. На экране это справа от чёрного ферзя.']
];
const whiteSide=Object.fromEntries([...whiteBackRank.map(([,sq,piece])=>[sq,piece]),...[...'abcdefgh'].map(f=>[f+'2','P'])]);
BOARD_EXERCISES.push(...blackBackRank.map(([name,square,placePiece,taskTitle,prompt,hint],i)=>({
 ...make('build-black-'+name,{...whiteSide,...Object.fromEntries(blackBackRank.slice(0,i).map(([,sq,piece])=>[sq,piece]))},[square],taskTitle,prompt,hint,i===7?'Верхний ряд чёрных собран. Чёрные пешки и самостоятельная сборка всей доски ещё впереди.':'Чёрная фигура на месте. Постепенно собираем верхний ряд.'),goal:'placePiece',placePiece
})));
